('bmlt-semen-analysis-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',2601,$json${"question":"The recommended abstinence period before routine semen analysis is generally","translation":"","options":["2–7 days","Less than 1 hour","14–21 days","No abstinence is required"],"correctIndex":0,"explanation":"A standardized abstinence period improves comparability of semen results.","explanationNe":"सामान्यतया २–७ दिनको abstinence ले semen नतिजा तुलना गर्न सजिलो बनाउँछ।","topic":"Pre-analytical"}$json$::jsonb,true),
