('bmlt-semen-analysis-mock-003','BMLT','BMLT NHPC Licensing','mock','free',2628,$json${"question":"A semen specimen arrives two hours after collection and has been kept cold. What is the main concern?","translation":"","options":["Motility may be altered, so document conditions and follow laboratory acceptance policy","Cold storage always improves motility","The sample is automatically sterile","Only pH is affected"],"correctIndex":0,"explanation":"Delayed and cold transport can affect motility; results need appropriate qualification or recollection.","explanationNe":"ढिलाइ र चिसो तापक्रमले motility असर गर्न सक्छ; lab policy अनुसार टिप्पणी वा पुनः नमुना आवश्यक हुन सक्छ।","topic":"Transport"}$json$::jsonb,true),
