('bmlt-semen-analysis-mock-009','BMLT','BMLT NHPC Licensing','mock','free',2634,$json${"question":"A semen sample is contaminated with lubricant. What is the likely effect?","translation":"","options":["Some lubricants may impair sperm motility or interfere with analysis","It always increases sperm count","It sterilizes the specimen safely","It has no possible effect"],"correctIndex":0,"explanation":"Lubricants may be spermatotoxic or interfere with specimen quality; approved collection methods are preferred.","explanationNe":"केही lubricant ले शुक्राणुको motility घटाउन वा परीक्षणमा असर गर्न सक्छन्।","topic":"Specimen collection"}$json$::jsonb,true),
